import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import * as A from '../src/astronomy.mjs';import * as P from '../src/projection.mjs';import {SkyController,projectCatalogue} from '../src/scene.mjs';
import {timeScales} from '../src/time-scales.mjs';
const cat=JSON.parse(fs.readFileSync(new URL('../data/bright-stars.json',import.meta.url))),by=new Map(cat.stars.filter(s=>s.hip!=null).map(s=>[s.hip,s]));
const base={utcMs:Date.UTC(2026,0,15,2),latDeg:28.54,lonDeg:-81.38},ori=[27989,25336,24436,27366,25930,26311,26727];
const near=(a,b,t=1e-8)=>assert.ok(Math.abs(a-b)<t,`${a}!=${b}`);
test('all seven Orion anchors aboveFlorida and in a single south-pointing camera',()=>{const frame=A.observationFrame(base);for(const id of ori){const h=A.observeStar(by.get(id),frame);assert.ok(h.aboveHorizon);assert.ok(P.projectPerspective(h,{azDeg:180,altDeg:45})?.visible);}});
test('same real Orion sources are not artificially inserted in northern legacy crop',()=>{const h=ori.map(id=>A.observeStar(by.get(id),base));assert.ok(h.some(s=>!P.projectWidgetDome(s).visible));});
test('physical source catalogue stable whileFlorida andMadinah sky geometry differs',()=>{const a=A.observeStar(by.get(32349),base),b=A.observeStar(by.get(32349),{...base,latDeg:24.47,lonDeg:39.61});assert.ok(A.angularSeparation(a.enu,b.enu)>50);assert.equal(by.get(32349).id,'hyg:32263');});
test('Polaris tracks northern latitude to within its polar separation across24hours',()=>{for(const lat of [0,24.47,28.54,64.15,89.9])for(let hour=0;hour<24;hour++){const h=A.observeStar(by.get(11767),{...base,latDeg:lat,utcMs:base.utcMs+hour*3600000});assert.ok(Math.abs(h.altDeg-lat)<.8);}});
test('Canopus and mainCrux never rise inReykjavik over a sidereal-day sample',()=>{for(let n=0;n<96;n++){const f=A.observationFrame({...base,latDeg:64.15,lonDeg:-21.94,utcMs:base.utcMs+n*900000});for(const id of [30438,60718,61084,62434,59747])assert.equal(A.observeStar(by.get(id),f).aboveHorizon,false);}});
test('Crux has a real rising/visible window inSydney, not a latitude-only switch',()=>{let up=0;for(let n=0;n<96;n++){const f=A.observationFrame({...base,latDeg:-33.86,lonDeg:151.21,utcMs:base.utcMs+n*900000});if([60718,61084,62434,59747].every(id=>A.observeStar(by.get(id),f).aboveHorizon))up++;}assert.ok(up>0);});
test('observer longitude+180 and-180 are the same meridian',()=>{const a=A.observeStar(by.get(32349),{...base,lonDeg:180}),b=A.observeStar(by.get(32349),{...base,lonDeg:-180});near(A.angularSeparation(a.enu,b.enu),0,1e-9);});
test('clock seek forward then back recovers exact state despite constant scene identity',()=>{const c=new SkyController(cat),first=c.update(base,{sceneIdentity:'held'}),later=c.update({...base,utcMs:base.utcMs+7200000},{sceneIdentity:'held'}),back=c.update(base,{sceneIdentity:'held'});assert.notDeepEqual(first.sources[0].enu,later.sources[0].enu);assert.deepEqual(first.sources,back.sources);});
test('midnight does not reset or jump the sidereal sky',()=>{const ms=Date.UTC(2026,0,15,23,59,59),a=A.observeStar(by.get(32349),{...base,utcMs:ms}),b=A.observeStar(by.get(32349),{...base,utcMs:ms+2000});const d=A.angularSeparation(a.enu,b.enu)*3600;assert.ok(d>20&&d<32,d);});
test('hidden-return caller can sample currentUTC directly without integrating a backlog',()=>{const c=new SkyController(cat);c.update(base);const returned=c.update({...base,utcMs:base.utcMs+3600000}),direct=projectCatalogue(cat,{...base,utcMs:base.utcMs+3600000});assert.deepEqual(returned.sources,direct);});
test('accepted external current barycentric state owns position and velocity',()=>{const ts=timeScales(base),earth=A.earthState(ts.jdTt),f=A.observationFrame({...base,earthBarycentric:{jdTt:ts.jdTt,frame:'mean-J2000',...earth}});assert.ok(!f.warnings.includes('heliocentric-earth-approximation'));const a=A.observeStar(by.get(32349),f),b=A.observeStar(by.get(32349),base);near(A.angularSeparation(a.enu,b.enu),0,1e-9);});
test('apparent horizon/refraction and geometric horizon are separately exposed',()=>{const f=A.observationFrame({...base,latDeg:0,meanOnly:true,pressureHpa:1010}),eqDate={raDeg:f.lstDeg+90.2,decDeg:0};const v=A.radecVector(eqDate.raDeg,eqDate.decDeg),columns=f.rotation,j2000=A.vectorRaDec(columns.map(c=>A.dot(c,v)));const h=A.observeStar(j2000,f);assert.equal(h.aboveGeometricHorizon,false);assert.equal(h.aboveHorizon,true);assert.ok(h.refractionDeg>.2);});
test('catalogue is seed-independent and produces no new synthetic source identifiers',()=>{const a=new SkyController(cat).update(base),b=new SkyController(cat).update({...base,seed:12345});assert.deepEqual(a.sources,b.sources);assert.ok(a.sources.every(s=>s.id.startsWith('hyg:')));});
